      hostTools[canonicalName] = {
        ...tool,
        execute: (input, executeOptions) =>
          executeCanonicalHostTool(
            () => execute(input, executeOptions),
            validator,
            input,
            executeOptions,
            canonicalName,
            captures,
          ),
      };
    }
    return hostTools;
  });

