const gradeRouting = (
  evalCase: PluginEvalCase,
  observation: PluginEvalObservation,
): PluginEvalDimensionScore => {
  const actual = observation.tool_calls.map((call) => call.name);
  const routing = evalCase.expected.routing;

  switch (routing.kind) {
    case "exact":
