        ? pass(`selected acceptable tool ${actual[0]}`)
        : fail(
            `expected one of ${routing.tools.join(", ")}; observed ${actual.join(", ") || "no tool"}`,
          );
    case "sequence":
      return actual.length === routing.tools.length &&
